import{_ as r,o as a,c as d,a2 as o}from"./chunks/framework.wVcpyw2-.js";const b=JSON.parse('{"title":"优惠券与营销","description":"灵萌平台营销券中心配置：券模板、区域配置、营销活动、发放核销与数据看板操作步骤。","frontmatter":{"title":"优惠券与营销","description":"灵萌平台营销券中心配置：券模板、区域配置、营销活动、发放核销与数据看板操作步骤。"},"headers":[],"relativePath":"features/coupon.md","filePath":"features/coupon.md","lastUpdated":1785020677000}'),e={name:"features/coupon.md"};function n(s,t,l,i,h,g){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="优惠券与营销" tabindex="-1">优惠券与营销 <a class="header-anchor" href="#优惠券与营销" aria-label="Permalink to &quot;优惠券与营销&quot;">​</a></h1><p>路径：<strong>平台推广 → 平台营销券中心</strong></p><p>配置平台级营销优惠券：建模板 → 开区域 → 做活动 → 发放/核销 → 看数据。<br> 推广员拉新请看 <a href="/features/promotion">推广员体系</a>（同属平台推广分组）。</p><hr><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>营销券相关模块已开通（<strong>系统设置 → 我的模块</strong>）</li><li>若券涉及购券/支付抵扣，须先完成 <a href="/features/payment">支付</a></li><li>已创建目标区域</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>本文是<strong>平台营销券</strong>。外卖商家自己的店铺优惠，在 <strong>商户管理 → 外卖</strong> 下配置，不在这里。</p></div><hr><h2 id="推荐操作顺序" tabindex="-1">推荐操作顺序 <a class="header-anchor" href="#推荐操作顺序" aria-label="Permalink to &quot;推荐操作顺序&quot;">​</a></h2><table tabindex="0"><thead><tr><th>顺序</th><th>菜单</th><th>做什么</th></tr></thead><tbody><tr><td>1</td><td><strong>券模板</strong></td><td>定义面额、门槛、有效期、券种</td></tr><tr><td>2</td><td><strong>区域配置</strong></td><td>各区域是否启用、预算/补贴上限</td></tr><tr><td>3</td><td><strong>营销活动</strong> / <strong>营销配置</strong></td><td>领取规则、投放方式</td></tr><tr><td>4</td><td><strong>券包商品</strong>（可选）</td><td>可购买的券包</td></tr><tr><td>5</td><td><strong>发放营销券</strong></td><td>运营手动发券</td></tr><tr><td>6</td><td><strong>营销券列表</strong> / <strong>核销记录</strong></td><td>查用户持券与使用</td></tr><tr><td>7</td><td><strong>运营看板</strong> / <strong>归因漏斗</strong></td><td>看效果</td></tr><tr><td>8</td><td><strong>补贴审批</strong> / <strong>A/B 实验</strong></td><td>高级能力，按需</td></tr></tbody></table><hr><h2 id="分步说明" tabindex="-1">分步说明 <a class="header-anchor" href="#分步说明" aria-label="Permalink to &quot;分步说明&quot;">​</a></h2><h3 id="_1-券模板" tabindex="-1">1. 券模板 <a class="header-anchor" href="#_1-券模板" aria-label="Permalink to &quot;1. 券模板&quot;">​</a></h3><p>路径：<strong>平台推广 → 平台营销券中心 → 券模板</strong></p><ol><li>新建模板</li><li>填写名称、券种（如满减/折扣，以页面选项为准）、面额或折扣、使用门槛、有效期</li><li>保存后供活动和发放引用</li></ol><p>同一模板可被多个活动复用。</p><h3 id="_2-区域配置" tabindex="-1">2. 区域配置 <a class="header-anchor" href="#_2-区域配置" aria-label="Permalink to &quot;2. 区域配置&quot;">​</a></h3><p>路径：<strong>… → 区域配置</strong></p><p>按区域打开营销券能力，设置预算或补贴上限（字段以页面为准）。<br> 未开区域的用户可能无法领取对应活动券。</p><h3 id="_3-营销活动与营销配置" tabindex="-1">3. 营销活动与营销配置 <a class="header-anchor" href="#_3-营销活动与营销配置" aria-label="Permalink to &quot;3. 营销活动与营销配置&quot;">​</a></h3><table tabindex="0"><thead><tr><th>菜单</th><th>作用</th></tr></thead><tbody><tr><td><strong>营销活动</strong></td><td>创建具体投放：时间、对象、关联模板、库存</td></tr><tr><td><strong>营销配置</strong></td><td>更偏全局/运营策略类开关（以页面为准）</td></tr></tbody></table><p>创建活动时注意：时间窗、每人限领、是否仅新用户等。</p><h3 id="_4-发放营销券" tabindex="-1">4. 发放营销券 <a class="header-anchor" href="#_4-发放营销券" aria-label="Permalink to &quot;4. 发放营销券&quot;">​</a></h3><p>路径：<strong>… → 发放营销券</strong></p><p>向指定用户手动发券（客服补偿、活动奖励等）。发放后可在 <strong>营销券列表</strong> 核对。</p><h3 id="_5-核销与数据" tabindex="-1">5. 核销与数据 <a class="header-anchor" href="#_5-核销与数据" aria-label="Permalink to &quot;5. 核销与数据&quot;">​</a></h3><table tabindex="0"><thead><tr><th>菜单</th><th>作用</th></tr></thead><tbody><tr><td><strong>核销记录</strong></td><td>券被哪笔订单使用</td></tr><tr><td><strong>运营看板</strong></td><td>整体领取/核销概况</td></tr><tr><td><strong>归因漏斗</strong></td><td>转化路径分析</td></tr><tr><td><strong>补贴审批</strong></td><td>涉及平台补贴时的审批流</td></tr><tr><td><strong>A/B 实验</strong></td><td>对比不同券策略</td></tr></tbody></table><hr><h2 id="验证是否生效" tabindex="-1">验证是否生效 <a class="header-anchor" href="#验证是否生效" aria-label="Permalink to &quot;验证是否生效&quot;">​</a></h2><ol><li>建一张小额测试模板，区域配置已启用</li><li>建进行中的活动，测试号在客户端能领取</li><li><strong>营销券列表</strong> 可见持券</li><li>下单满足门槛后抵扣成功，<strong>核销记录</strong> 有数据</li><li>看板数字有更新</li></ol><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>处理</th></tr></thead><tbody><tr><td>领不了券</td><td>区域是否关闭；活动是否过期；库存/限领是否满；用户是否符合人群</td></tr><tr><td>下单不能用</td><td>门槛未满足；券状态；业务类型是否允许用该券</td></tr><tr><td>侧栏没有营销券</td><td>模块未开通或无权限</td></tr><tr><td>补贴发不出</td><td>看 <strong>补贴审批</strong> 是否卡在待审</td></tr></tbody></table><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/features/promotion">推广员体系</a></li><li><a href="/features/payment">支付与提现</a></li><li><a href="/features/finance">财务流水与提现</a></li><li><a href="/features/lottery">抽奖活动</a></li></ul>',36)])])}const u=r(e,[["render",n]]);export{b as __pageData,u as default};
